text:
{
  "title_novice": "Фронт приливной дельты: веер гряд",
  "summary": [
    {"text": "Фронт приливной дельты образуют песчаные гряды, расположенные радиально от устьев рукавов.", "claims": ["c1"]},
    {"text": "Гряды могут быть до 2 км длиной, 300 м шириной и 10–22 м высотой.", "claims": ["c2"]},
    {"text": "Дальше от устья течения слабеют и осадка становится меньше — это дистальные гряды.", "claims": ["c6", "c7"]}
  ],
  "claims": [
    {"key": "c1", "text": "Главные черты фронта приливной дельты — гряды, расположенные радиально относительно устьев рукавов.", "kind": "observation", "unit_id": "u-044-f7014b", "page": 44, "quote": "Основными чертами фронта дельты являются приливные гряды, радиально расположенные по отношению к устьям рукавов.", "numbers": [], "question": null},
    {"key": "c2", "text": "Гряды могут достигать 2 км в длину, 300 м в ширину и 10–22 м в высоту.", "kind": "observation", "unit_id": "u-044-f7014b", "page": 44, "quote": "Они могут достигать в длину 2км, ширину 300м и 10–22м по высоте.", "numbers": ["2", "300", "10–22"], "question": null},
    {"key": "c3", "text": "Между грядами есть каналы; в них встречаются отмели и бары, формы дна которых согласованы с течениями.", "kind": "observation", "unit_id": "u-044-f7014b", "page": 44, "quote": "В каналах между грядами встречаются отмели и бары с донными формами рельефа, согласующимися с направлением паводковых и приливно-отливных течений.", "numbers": [], "question": null},
    {"key": "c4", "text": "Пески гряд в верхах регрессивного разреза фронта дельты имеют двунаправленную мульдообразную косую слоистость.", "kind": "observation", "unit_id": "u-044-f7014b", "page": 44, "quote": "пески приливных гряд верхов регрессивного типа разреза фронта дельты характеризуются двунаправленной мульдообразной косой слоистостью", "numbers": [], "question": null},
    {"key": "c5", "text": "В песках гряд есть случайные глинистые слойки и многочисленные мелкие каналы.", "kind": "observation", "unit_id": "u-044-f7014b", "page": 44, "quote": "со случайными глинистыми слойками и многочисленными мелкими каналами", "numbers": [], "question": null},
    {"key": "c6", "text": "Рисунок 1.25 показывает проксимальные гряды, которые подвержены воздействию приливов.", "kind": "observation", "unit_id": "u-043-e58704", "page": 43, "quote": "проксимальных приливных песчаных гряд, подверженных воздействию приливов (c)", "numbers": [], "question": null},
    {"key": "c7", "text": "Дистальные гряды лежат дальше: там осадка мало и приливные течения ослаблены.", "kind": "observation", "unit_id": "u-043-e58704", "page": 43, "quote": "до дистальных песчаных гряд (d), где количество осадка ограничено и приливные течения ослаблены", "numbers": [], "question": null},
    {"key": "c8", "text": "Описанная двунаправленная косая слоистость относится к идеализированному разрезу, а не к каждому разрезу.", "kind": "assumption", "unit_id": "u-044-f7014b", "page": 44, "quote": "В идеализированном разрезе этой дельты", "numbers": [], "question": null},
    {"key": "c9", "text": "Рисунок 1.25 — трёхмерная модель фронта и нижней равнины одной приливной дельты.", "kind": "observation", "unit_id": "u-043-e58704", "page": 43, "quote": "Трехмерная модель фронта дельты и нижней дельтовой равнины приливной дельты эоценовой свиты Мисоа (Венесуэла)", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Гряды расположены радиально: они расходятся от устьев рукавов, как спицы от центра.", "claims": ["c1"], "hypothesis": false},
    {"text": "Между грядами идут каналы. В них встречаются отмели и бары.", "claims": ["c3"], "hypothesis": false},
    {"text": "Формы дна в каналах согласуются с направлением паводковых и приливно-отливных течений.", "claims": ["c3"], "hypothesis": false},
    {"text": "В песках верхов регрессивного разреза видна двунаправленная мульдообразная косая слоистость.", "claims": ["c4"], "hypothesis": false},
    {"text": "Двунаправленная слоистость означает, что течения шли то в одну, то в другую сторону.", "claims": ["c4"], "hypothesis": true},
    {"text": "В песках встречаются случайные глинистые слойки и мелкие каналы.", "claims": ["c5"], "hypothesis": false},
    {"text": "По рисунку 1.25 гряды делятся на проксимальные (c) и дистальные (d).", "claims": ["c6", "c7"], "hypothesis": false},
    {"text": "Проксимальные гряды подвержены воздействию приливов. Дистальные — с ослабленными приливными течениями.", "claims": ["c6", "c7"], "hypothesis": false},
    {"text": "Ближе к устью осадка больше, дальше его меньше. Это логика подписи, а не прямое число.", "claims": ["c7"], "hypothesis": true}
  ],
  "practice": [
    {"text": "Гряду узнают по косой слоистости в верхах регрессивного разреза фронта дельты.", "claims": ["c4"], "hypothesis": false},
    {"text": "Признаки песков гряды: двунаправленная мульдообразная косая слоистость, глинистые слойки, мелкие каналы.", "claims": ["c4", "c5"], "hypothesis": false},
    {"text": "Размеры гряд берут как верхнюю границу: гряды «могут достигать» указанных значений.", "claims": ["c2"], "hypothesis": false},
    {"text": "Положение точки относительно устья рукава определяет, проксимальная она или дистальная гряда.", "claims": ["c6", "c7"], "hypothesis": true},
    {"text": "Рисунок 1.25 удобно использовать как опорную схему: протоки, проксимальные гряды и дистальные гряды.", "claims": ["c9"], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Описанная слоистость идеализирована. Реальные разрезы могут отличаться.", "claims": ["c8"], "hypothesis": false},
    {"text": "Размеры даны как максимум: гряды «могут достигать» 2 км, 300 м и 10–22 м.", "claims": ["c2"], "hypothesis": false},
    {"text": "Рисунок 1.25 показывает одну приливную дельту, а не общий эталон для всех дельт.", "claims": ["c9"], "hypothesis": false},
    {"text": "Фронт волновой дельты устроен иначе; см. узлы о волновых дельтах (n26–n29).", "claims": [], "hypothesis": true},
    {"text": "Форма гряд и течения зависят от приливов, климата и рельефа. Единой формулы в главе нет.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Почему течения слабеют с удалением от устья", "text": "Гипотеза: поток теряет силу по мере растекания и трения о дно. В главе точного механизма нет.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Длина гряды: могут достигать 2 км.", "claims": ["c2"]},
    {"text": "Ширина гряды: могут достигать 300 м.", "claims": ["c2"]},
    {"text": "Высота гряды: 10–22 м.", "claims": ["c2"]},
    {"text": "Гряды радиальны относительно устьев рукавов.", "claims": ["c1"]},
    {"text": "Дистальные гряды: осадка мало, приливные течения ослаблены.", "claims": ["c7"]}
  ],
  "terms_defined": [
    {"term": "радиальные приливные гряды", "term_en": "radial tidal ridges", "abbr": "", "definition": "Песчаные гряды приливной дельты, расположенные лучами от устьев рукавов. Могут быть до 2 км длиной.", "claims": ["c1", "c2"]},
    {"term": "проксимальный", "term_en": "proximal", "abbr": "", "definition": "Ближний к источнику. Для гряд — ближе к устьям рукавов, где сильнее воздействие приливов.", "claims": ["c6"]},
    {"term": "дистальный", "term_en": "distal", "abbr": "", "definition": "Дальний от источника. Для гряд — дальше от устьев: осадка мало, течения слабее.", "claims": ["c7"]}
  ],
